                      txt('ld2LsAppraisalPrice', si.lsAppraisalPrice);
                      txt('ld2LsAppraisalCompany', si.lsAppraisalCompanyPrice);   /* ชื่อบริษัทประเมิน — ยืนยันจาก user (ชื่อ key มีคำว่า Price แต่เก็บชื่อบริษัท ไม่ใช่ตัวเลข) */
                      txt('ld2LsLoanAmount', si.lsLoanAmount);
